window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"IHnuNlH7eyw","speaker":"Duma Gideon Boko","role":"President","country":"Botswana","region":"Africa","url":"https://www.youtube.com/watch?v=IHnuNlH7eyw","date":"20260923","title":"🇧🇼 Botswana - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":910,"words":1651,"counts":{"claims":21,"promises":0,"attacks":0},"topics":[{"topic":"Botswana health","share":0.1633,"seconds":149},{"topic":"UN legitimacy","share":0.1557,"seconds":142},{"topic":"AI governance","share":0.0917,"seconds":83},{"topic":"Botswana finance","share":0.0861,"seconds":78},{"topic":"UN norms","share":0.0773,"seconds":70},{"topic":"Development finance","share":0.0772,"seconds":70},{"topic":"Multilateralism","share":0.077,"seconds":70},{"topic":"UN reform","share":0.0763,"seconds":69},{"topic":"Botswana environment","share":0.0746,"seconds":68},{"topic":"Botswana diplomacy","share":0.0663,"seconds":60},{"topic":"Botswana politics","share":0.0544,"seconds":50}],"timeline":[[4,75,null],[78,154,"UN legitimacy"],[155,225,"Multilateralism"],[227,287,"Botswana diplomacy"],[289,359,"UN norms"],[361,429,"Botswana environment"],[431,501,"Development finance"],[503,581,"Botswana finance"],[583,652,"Botswana health"],[654,733,"Botswana health"],[735,804,"UN reform"],[806,890,"AI governance"],[892,958,"UN legitimacy"],[960,1009,"Botswana politics"]],"stances":{"UN legitimacy":"Duma Gideon Boko states that restoring trust requires fidelity to the UN Charter and international law, while managing transformation requires adaptable institutions.","Multilateralism":"Duma Gideon Boko argues that strengthening multilateralism is essential for the UN to deliver results and that Botswana's security and prosperity rely on disciplined integration into a rules-based community of nations.","Botswana diplomacy":"Duma Gideon Boko asserts that Botswana honors treaty obligations and views compliance with international law as a vital protection for the nation.","UN norms":"Duma Gideon Boko asserts that international rules must apply equally to all nations and calls for a renewed commitment to dialogue as the primary method of resolving conflicts.","Botswana environment":"Duma Gideon Boko states that climate change directly affects Botswana's livelihoods, water security, and biodiversity, and emphasizes the need to invest in Africa's young population to avoid a demographic crisis.","Development finance":"The speaker argues that the global financial architecture must evolve to address the economic realities of developing nations, particularly regarding borrowing costs and climate financing.","Botswana finance":"Duma Gideon Boko argues that current debt servicing undermines development and calls for reforms to global financial governance to ensure fair access for developing countries.","Botswana health":"Duma Gideon Boko states that Botswana successfully built a comprehensive HIV treatment program and achieved international targets through national leadership and global partnership.","UN reform":"Botswana supports comprehensive Security Council reform and aligns with the African position to address inequities, arguing that excluding Africa and Latin America from permanent membership undermines the Council's credibility.","AI governance":"Duma Gideon Boko calls for an inclusive international framework on emerging technologies where developing countries have a meaningful voice in setting standards.","Botswana politics":"Duma Gideon Boko states that Botswana is ready to partner with all member states, emphasizing its steady principles and offering expertise in health, resource stewardship, and dialogue."},"claims":[{"t":121,"quote":"our declarations, communiques, and must travel the difficult road from this Assembly Hall to the daily lives of the peoples we represent.","topic":"UN legitimacy","kind":"fact"},{"t":143,"quote":"world is undergoing transformation driven by technology, climate change, demographic shifts, and changing patterns of economic power.","topic":"UN legitimacy","kind":"fact"},{"t":175,"quote":"Whether a nation of a billion people, or like Botswana with just over 2 and 1/2 million people","topic":"Multilateralism","kind":"number"},{"t":210,"quote":"When Botswana gained independence in we carried a founding belief that our security and prosperity would come from disciplined integration into a community of nations governed by rules that all had agreed to honor.","topic":"Multilateralism","kind":"fact"},{"t":227,"quote":"We honored our treaty obligations and opened our economy in accordance with the norms of this organization.","topic":"Botswana diplomacy","kind":"fact"},{"t":235,"quote":"We regarded compliance with international law as one of Botswana's strongest protections.","topic":"Botswana diplomacy","kind":"fact"},{"t":321,"quote":"Botswana has sought to live by this principle as a host to the Southern African Development Community SADC through our contributions to regional mediation and election observation","topic":"UN norms","kind":"fact"},{"t":346,"quote":"Climate change is no longer tomorrow's It is today's drought in Africa, floods in Asia, rising seas in the Pacific, and wildfires in Europe and the Americas","topic":"UN norms","kind":"fact"},{"t":361,"quote":"For Botswana, custodian of the Okavango Delta, a UNESCO World Heritage Site, and the Kalahari ecosystem, climate change directly affects livelihoods, water security, and biodiversity.","topic":"Botswana environment","kind":"fact"},{"t":386,"quote":"Africa has the youngest population on That is an extraordinary asset if we invest in it.","topic":"Botswana environment","kind":"fact"},{"t":487,"quote":"Developing countries frequently face borrowing costs several times higher than those of wealthier nations because the system was not designed with the circumstances of the global South in mind.","topic":"Development finance","kind":"fact"},{"t":572,"quote":"Three decades ago, our country faced an HIV AIDS pandemic of such severity that some questioned our long-term resilience.","topic":"Botswana finance","kind":"fact"},{"t":596,"quote":"We achieved the UNAIDS 95-95-95 targets ahead of schedule, and we became the first African country to achieve World Health Organization silver tier status for the elimination of mother-to-child transmission of HIV.","topic":"Botswana health","kind":"fact"},{"t":654,"quote":"That partnership helped to mitigate an epidemic by means of one of the world's most successful national responses, and placed Botswana firmly on the path towards ending HIV AIDS as a public health threat by 2030.","topic":"Botswana health","kind":"fact"},{"t":764,"quote":"Mr. President, no reform agenda, including UN 80, is complete without addressing the long-standing inequities within the Security Council.","topic":"UN reform","kind":"fact"},{"t":793,"quote":"We believe that a Security Council that continues to exclude Africa and Latin America from permanent membership cannot credibly claim to reflect contemporary geopolitical realities.","topic":"UN reform","kind":"fact"},{"t":819,"quote":"We recognize technology as a bridge that narrows global inequality.","topic":"AI governance","kind":"fact"},{"t":826,"quote":"This extends to critical minerals, rare earths, and energy resources that power the technological revolution, many of which come from developing countries.","topic":"AI governance","kind":"fact"},{"t":903,"quote":"We restore trust when we uphold our commitments, respect the UN Charter, and apply international law consistently.","topic":"UN legitimacy","kind":"fact"},{"t":948,"quote":"The difference our decisions make in the lives and livelihoods of people is the standard against which the credibility of the United Nations must be measured.","topic":"UN legitimacy","kind":"fact"},{"t":969,"quote":"We offer partnership in governance that delivers experience in health responsible stewardship of natural and mineral resources and enduring preference for dialogue.","topic":"Botswana politics","kind":"fact"}],"promises":[],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":4,"topic":null,"text":"The assembly will now hear an address by his Excellency Dr. Mokgweetsi Eric Keabetswe Masisi, President of the Republic of Botswana. I request protocol to escort his Excellency and invite him to address the &gt;&gt; Mr. President, Botswana warmly congratulates you on your election to preside over the 81st session of the United Nations General Assembly. We assure you of our full support as you shoulder this important responsibility. We also commend the outgoing president for a distinguished stewardship. Her tenure reminds us of an unfinished chapter in the history of this Eight decades later, the United Nations has yet to be led by a woman as Secretary-General."},{"t":78,"topic":"UN legitimacy","text":"Mr. President, the theme of this \"Restoring trust, managing transformation, a United Nations that delivers for all\", aptly captures the central challenge before us. Restoring trust requires fidelity to the UN Charter and international law. Managing transformation requires institutions capable of adapting to a rapidly changing world and delivering for all requires us to move beyond declarations towards tangible improvements in the lives and livelihoods of our peoples. our declarations, communiques, and must travel the difficult road from this Assembly Hall to the daily lives of the peoples we represent. Persistent conflicts, geopolitical tensions, and growing divisions have tested trust between our world is undergoing transformation driven by technology, climate change, demographic shifts, and changing patterns of economic power."},{"t":155,"topic":"Multilateralism","text":"The pertinent question is how we strengthen multilateralism so that the United Nations can deliver meaningful results for all member Humanity has traveled far enough to know that on the great challenges of our age, none of us can go it alone. Whether a nation of a billion people, or like Botswana with just over 2 and 1/2 million people, we share one fragile planet and one imperfect but irreplaceable United The choices we make will determine whether multilateralism restores trust, manages transformation, and delivers for all, or becomes a cautionary tale of promises made and forgotten. Botswana comes to this podium with a power and weight of genuine conviction. When Botswana gained independence in we carried a founding belief that our security and prosperity would come from disciplined integration into a community of nations governed by rules that all had agreed to honor."},{"t":227,"topic":"Botswana diplomacy","text":"We honored our treaty obligations and opened our economy in accordance with the norms of this organization. We regarded compliance with international law as one of Botswana's strongest protections. That is the tradition I bring to this representing a nation staking its existence on the promise that shared rules, faithfully observed, remain humanity's best instrument for peace and That tradition tests whether trust between nations, large and small, can be Mr. President, restoring trust must begin with restoring respect. Respect for sovereignty, territorial integrity, and equal dignity of every nation, regardless of its size, wealth, or military power. For smaller states such as Botswana, a rule-based international order is an essential safeguard."},{"t":289,"topic":"UN norms","text":"It assures us that international relations will be by the strength of agreed principles. Botswana believes that rules that bind only the weak are not rules, and principles applied selectively soon cease to command respect. That is why Botswana calls on this General Assembly, the Security Council, and every organ of the United Nations to recommit to dialogue as the first instrument of Botswana has sought to live by this principle as a host to the Southern African Development Community SADC through our contributions to regional mediation and election observation, and through our consistent commitment to the peaceful peaceful settlement of Mr. President, even as we work to restore trust, our world is transforming. Climate change is no longer tomorrow's It is today's drought in Africa, floods in Asia, rising seas in the Pacific, and wildfires in Europe and the Americas."},{"t":361,"topic":"Botswana environment","text":"For Botswana, custodian of the Okavango Delta, a UNESCO World Heritage Site, and the Kalahari ecosystem, climate change directly affects livelihoods, water security, and biodiversity. Botswana remains committed to the 30 by 30 target, and the sustainable management of our natural capital. Mr. President, Africa has the youngest population on That is an extraordinary asset if we invest in it. But what is a demographic dividend today, can become a demographic crisis if opportunity does not keep pace with Youth unemployment remains one of the most urgent challenges of our time. Managing it is a shared responsibility. Botswana calls upon the United Nations Development Program, the International Labor Organization, and all relevant multilateral institutions to make technology transfer, skills development, and capacity building funded priorities."},{"t":431,"topic":"Development finance","text":"As we will all agree, the credibility of our multilateral commitments will be properly tested in development finance. When countries have the means to invest in their people, and when international institutions respond effectively to shared threats, trust is strengthened. But when commitments remain out of reach for those who need them most, confidence in the system weakens. Getting these fundamentals right is central to restoring trust, managing and building a United Nations that delivers for all. The global financial architecture must therefore evolve to reflect the economic realities of the 21st century, including financing demands created by climate change, technological transformation, and the imperative for sustainable development. Developing countries frequently face borrowing costs several times higher than those of wealthier nations because the system was not designed with the circumstances of the global South in mind."},{"t":503,"topic":"Botswana finance","text":"Debt sustainability is a question of development and fairness. When nations spend more to service debt than invest in education, job creation, or provision of health care, trust in the system erodes. Botswana calls upon this Assembly and the international financial institutions to pursue reform of global financial governance. This would give developing countries a meaningful voice and provide fair and predictable access to concessional We call upon the United Nations and its financial partners to mobilize private capital through innovative and blended financing agreements that de-risk productive investment in developing economies. This is enlightened fairness and sound Capital should help create opportunity where its impact can be found. Mr. President, health is where the promise of international solidarity is tested most And Botswana speaks from hard-earned Three decades ago, our country faced an HIV AIDS pandemic of such severity that some questioned our long-term resilience."},{"t":583,"topic":"Botswana health","text":"Through determined national leadership, bold public investment, and sustainable global partnership, Botswana built one of the world's most comprehensive HIV AIDS treatment programs. We achieved the UNAIDS 95-95-95 targets ahead of schedule, and we became the first African country to achieve World Health Organization silver tier status for the elimination of mother-to-child transmission of HIV. Our experience demonstrates that when national ownership and international solidarity converge, seemingly impossible challenges can be This kind of practical solidarity restores confidence in multilateralism. We stand ready to share the lessons of this experience through South-South and triangular Botswana attaches particular importance to preserving UNAIDS, an indispensable partner in our national response through evidence-based policy technical assistance, resource mobilization, and global advocacy."},{"t":654,"topic":"Botswana health","text":"That partnership helped to mitigate an epidemic by means of one of the world's most successful national responses, and placed Botswana firmly on the path towards ending HIV AIDS as a public health threat by 2030. Mr. President, Botswana supports reforms that strengthen the effectiveness, coherence, and responsiveness of the United Nations We also believe that efficiency gains should be redeployed to strengthen the capacity of the organization to prevent conflict, address emerging security threats, and deliver meaningful results in program countries in line with the UN 80 vision. It is in this spirit that Botswana accords the highest priority to its partnerships with the United Nations Office of UN-Habitat, the International Trade the International Organization for Migration, among others. We particularly recognize UNOCT's leadership role in strengthening the United Nations collective efforts to prevent and counter-terrorism and violent and in translating international commitments into practical support for member states."},{"t":735,"topic":"UN reform","text":"Botswana remains committed to further deepening its cooperation with UNOCT and the wider United Nations system through capacity building, technical assistance, knowledge sharing, and the exchange of good practices. Such partnerships demonstrate that a responsive United Nations can build trust, strengthen national capacity, and foster peace and security. Mr. President, no reform agenda, including UN 80, is complete without addressing the long-standing inequities within the Security Council. In this regard, Botswana reaffirms its support for comprehensive Security Council reform, and aligns itself with the common African position as articulated in the Ezulwini Consensus and the Sirte We believe that a Security Council that continues to exclude Africa and Latin America from permanent membership cannot credibly claim to reflect contemporary geopolitical realities."},{"t":806,"topic":"AI governance","text":"We also call on the United Nations to continue to explore the creation of an inclusive international framework on emerging technologies, including artificial intelligence. We recognize technology as a bridge that narrows global inequality. This extends to critical minerals, rare earths, and energy resources that power the technological revolution, many of which come from developing countries. developing countries must have a meaningful voice in setting the standards and safeguards that will govern these technologies, ensuring that they expand opportunities, support decent work, and strengthen public services, while protecting human dignity, rights, and security. Mr. President, I wish to reaffirm Botswana's commitment to We believe that shared challenges require shared We also believe that implementing the Pact for the Future, together with the UN 80 initiative, offers an opportunity to translate our shared commitments into practical improvements in the functioning of the United Nations."},{"t":892,"topic":"UN legitimacy","text":"In conclusion, Mr. President, I that restoring trust, managing and delivering for all are We restore trust when we uphold our commitments, respect the UN Charter, and apply international law consistently. We manage transformation when change creates opportunity, rather than deepens inequality. When developing countries have a meaningful voice in shaping the that affect their future. And when technological and economic progress serve humanity as a whole. And we deliver for all when our decisions translate into tangible improvements in peace, security, development, health, and human The difference our decisions make in the lives and livelihoods of people is the standard against which the credibility of the United Nations must be measured."},{"t":960,"topic":"Botswana politics","text":"Botswana is ready to work with all member states. We may be small in size, but we are steady in principle. We offer partnership in governance that delivers experience in health responsible stewardship of natural and mineral resources and enduring preference for dialogue. Let us ensure that history remembers this 81st session for the trust we built, the promises kept, and the future created. I thank you. &gt;&gt; On behalf of the assembly I wish to thank the president of the Republic of Botswana."}],"compare":[{"topic":"UN & its reform","share":0.3093,"mean":0.2042,"rank":42,"others":170},{"topic":"Artificial Intelligence","share":0.0917,"mean":0.0503,"rank":40,"others":83},{"topic":"Global Economy","share":0.0772,"mean":0.0142,"rank":15,"others":31},{"topic":"International Law & Order","share":0.077,"mean":0.0603,"rank":61,"others":102},{"topic":"Botswana","share":0.0663,"mean":0.0,"rank":1,"others":0}]};
